1	package mevwatch
2	
3	import (
4		"encoding/json"
5		"math"
6		"reflect"
7		"strings"
8		"testing"
9	)
10	
11	func entry(index, term int, command string) LogEntry {
12		return LogEntry{Index: index, Term: term, Command: command}
13	}
