15	func run(t *testing.T, initial InitialState, requests ...AppendRequest) ReplicateOutput {
16		t.Helper()
17		out, err := Replicate(initial, requests)
18		if err != nil {
19			t.Fatalf("Replicate returned error: %v", err)
20		}
21		return out
22	}
23	
24	func expectError(t *testing.T, initial InitialState, requests []AppendRequest, fragments ...string) {
25		t.Helper()
26		_, err := Replicate(initial, requests)
27		if err == nil {
28			t.Fatalf("expected error, got nil")
29		}
30		message := err.Error()
31		for _, fragment := range fragments {
32			if !strings.Contains(message, fragment) {
33				t.Fatalf("error %q does not contain %q", message, fragment)
34			}
35		}
36	}
37	
38	func TestBasicAppendFromOrigin(t *testing.T) {
39		out := run(t, InitialState{CurrentTerm: 1},
40			AppendRequest{Term: 1, PrevLogIndex: 0, PrevLogTerm: 0, LeaderCommit: 0,
41				Entries: []LogEntry{entry(1, 1, "x"), entry(2, 1, "y")}},
42		)
43		if !out.Results[0].Accepted || out.Results[0].Reason != ReasonOK {
44			t.Fatalf("expected acceptance, got %+v", out.Results[0])
45		}
46		want := []LogEntry{entry(1, 1, "x"), entry(2, 1, "y")}
47		if !reflect.DeepEqual(out.FinalLog, want) {
48			t.Fatalf("log = %+v, want %+v", out.FinalLog, want)
49		}
50	}
51	
52	func TestStaleTermRejectionChangesNothing(t *testing.T) {
53		initial := InitialState{CurrentTerm: 5, CommittedIndex: 1,
54			Log: []LogEntry{entry(1, 5, "a")}}
55		out := run(t, initial,
56			AppendRequest{Term: 4, PrevLogIndex: 1, PrevLogTerm: 5, LeaderCommit: 1,
57				Entries: []LogEntry{entry(2, 4, "b")}},
58		)
59		result := out.Results[0]
60		if result.Accepted || !strings.Contains(result.Reason, "stale term") {
61			t.Fatalf("expected stale-term rejection, got %+v", result)
62		}
63		if result.Term != 5 || result.CommittedIndex != 1 {
64			t.Fatalf("state changed: %+v", result)
65		}
66		if !reflect.DeepEqual(out.FinalLog, initial.Log) {
67			t.Fatalf("log changed: %+v", out.FinalLog)
68		}
69	}
70	
71	// 较高任期即使因前缀不匹配被拒，任期更新也必须保留。
72	func TestHigherTermUpdateSurvivesPrefixRejection(t *testing.T) {
73		initial := InitialState{CurrentTerm: 2, Log: []LogEntry{entry(1, 2, "a")}}
74		out := run(t, initial,
75			AppendRequest{Term: 7, PrevLogIndex: 1, PrevLogTerm: 3, LeaderCommit: 0},
76		)
77		result := out.Results[0]
78		if result.Accepted {
79			t.Fatalf("expected rejection, got %+v", result)
80		}
81		if result.Term != 7 {
82			t.Fatalf("term should be updated to 7, got %d", result.Term)
83		}
84		if result.CommittedIndex != 0 || len(out.FinalLog) != 1 {
85			t.Fatalf("log/commit changed: ci=%d log=%+v", result.CommittedIndex, out.FinalLog)
86		}
87	}
88	
89	func TestHigherTermUpdateSurvivesIndexBeyondLog(t *testing.T) {
90		initial := InitialState{CurrentTerm: 2, Log: []LogEntry{entry(1, 2, "a")}}
91		out := run(t, initial,
92			AppendRequest{Term: 7, PrevLogIndex: 3, PrevLogTerm: 2},
93		)
94		if out.Results[0].Accepted {
95			t.Fatalf("expected rejection")
96		}
97		if out.Results[0].Term != 7 {
98			t.Fatalf("term should be 7, got %d", out.Results[0].Term)
99		}
100	}
101	
102	func TestPrevLogSentinelSemantics(t *testing.T) {
103		initial := InitialState{CurrentTerm: 3}
104		// 日志起点：索引 0 只与任期 0 匹配。
105		out := run(t, initial,
106			AppendRequest{Term: 3, PrevLogIndex: 0, PrevLogTerm: 1},
107		)
108		if out.Results[0].Accepted || !strings.Contains(out.Results[0].Reason, "prev log mismatch") {
109			t.Fatalf("expected prev mismatch for (0,1), got %+v", out.Results[0])
110		}
111		if out.Results[0].Term != 3 {
112			t.Fatalf("term changed: %d", out.Results[0].Term)
113		}
114		// 有日志时 (0,0) 表示新领导者从起点重传整个日志，应匹配成功。
115		initial = InitialState{CurrentTerm: 3, Log: []LogEntry{entry(1, 2, "old")}}
116		out = run(t, initial,
117			AppendRequest{Term: 3, PrevLogIndex: 0, PrevLogTerm: 0,
118				Entries: []LogEntry{entry(1, 3, "new")}},
119		)
120		if !out.Results[0].Accepted {
121			t.Fatalf("expected acceptance, got %+v", out.Results[0])
122		}
123		want := []LogEntry{entry(1, 3, "new")}
124		if !reflect.DeepEqual(out.FinalLog, want) {
125			t.Fatalf("log = %+v, want %+v", out.FinalLog, want)
126		}
127	}
128	
129	func TestPrevLogMissingOrWrongTerm(t *testing.T) {
130		initial := InitialState{CurrentTerm: 3, Log: []LogEntry{entry(1, 2, "a")}}
131		out := run(t, initial,
132			// prevLogIndex 超出日志长度。
133			AppendRequest{Term: 3, PrevLogIndex: 2, PrevLogTerm: 2},
134			// 索引存在但任期不同。
135			AppendRequest{Term: 3, PrevLogIndex: 1, PrevLogTerm: 3},
136		)
