978		if err := json.Unmarshal(encoded, &decoded); err != nil {
979			t.Fatal(err)
980		}
981		conflict, ok := decoded["conflict"].(map[string]any)
982		if !ok {
983			t.Fatalf("mismatch result should carry conflict object, got %s", encoded)
984		}
985		if conflict["index"] != float64(2) || conflict["term"] != float64(0) {
986			t.Fatalf("conflict = %v, want index 2 term 0", conflict)
987		}
988		// 编解码往返后反馈保持原样。
989		var roundTrip AppendResult
990		if err := json.Unmarshal(encoded, &roundTrip); err != nil {
991			t.Fatal(err)
992		}
993		if roundTrip.Conflict == nil || *roundTrip.Conflict != (ConflictHint{Index: 2, Term: 0}) {
994			t.Fatalf("round trip conflict = %+v, want {2 0}", roundTrip.Conflict)
