1589			`{"accepted":false,"reason":"stale term: leader term is lower than current term","term":3,"committedIndex":0,"APPLIEDINDEX":2,"ApplyError":{"index":3,"reason":"boom"}}` +
1590			`],"finalTerm":3,"finalCommittedIndex":0,"finalLog":[],` +
1591			`"FINALAPPLIEDINDEX":2,"FinalKV":{"k":"v"},"FINALAPPLYERROR":{"index":3,"reason":"boom"}}`
1592		var out1 ReplicateOutput
1593		if err := json.Unmarshal([]byte(data1), &out1); err != nil {
1594			t.Fatal(err)
1595		}
