1597		if err != nil {
1598			t.Fatal(err)
1599		}
1600		m1 := decodeMap(t, reencoded1)
1601		results1 := resultMaps(t, m1)
1602		mustLackKeys(t, results1[0], "plain request", perRequestKeys...)
1603		mustHaveKeys(t, results1[1], "applied request", perRequestKeys...)
1604		if results1[1]["appliedIndex"] != float64(2) ||
1605			!reflect.DeepEqual(results1[1]["applyError"],
1606				map[string]any{"index": float64(3), "reason": "boom"}) {
