317		if result.AppliedIndex != nil || result.ApplyError != nil {
318			t.Fatalf("applyKV disabled: result must omit apply fields: %+v", result)
319		}
320		if out.FinalAppliedIndex != nil || out.FinalKV != nil || out.FinalApplyError != nil {
321			t.Fatalf("applyKV disabled: output must omit apply fields: %+v", out)
322		}
323	
324		// 输入隔离：基准在调用后仍保持原值。
325		if !reflect.DeepEqual(initial, initialSnapshot) {
